<?php

declare(strict_types=1);

namespace OCA\TourCheck\Tests\Integration;

use OCP\Migration\IOutput;
use Test\TestCase;

/**
 * Resolves every repair step named in appinfo/info.xml <repair-steps> through
 * the real Nextcloud container — the exact resolution `occ upgrade` performs —
 * and runs idempotent Ensure* steps end-to-end.
 * Auto-generated by scripts/sync-app-di-guard-tests.php.
 */
final class UpgradeRepairIntegrationTest extends TestCase
{
	protected function setUp(): void
	{
		if (!class_exists(\OC::class) || !isset(\OC::$server)) {
			$this->markTestSkipped('Nextcloud is not bootstrapped (run inside Docker).');
		}
		parent::setUp();
	}

	public static function repairStepClassesFromInfoXml(): array
	{
		$xml = simplexml_load_string((string)file_get_contents(dirname(__DIR__, 2) . '/appinfo/info.xml'));
		$classes = [];
		foreach ($xml->{'repair-steps'}->children() as $phase) {
			foreach ($phase->step as $step) {
				$classes[] = (string)$step;
			}
		}
		$unique = array_values(array_unique($classes));
		return array_combine($unique, array_map(static fn (string $class): array => [$class], $unique));
	}

	public static function ensureStepClassesFromInfoXml(): array
	{
		$out = [];
		foreach (self::repairStepClassesFromInfoXml() as $class => $_) {
			$short = substr($class, (int)strrpos($class, '\\') + 1);
			if (str_starts_with($short, 'Ensure')) {
				$out[$class] = [$class];
			}
		}
		return $out;
	}

	/**
	 * @dataProvider repairStepClassesFromInfoXml
	 */
	public function testRepairStepResolvesFromContainer(string $class): void
	{
		$step = \OCP\Server::get($class);
		$this->assertInstanceOf($class, $step);
	}

	/**
	 * Ensure* steps are the idempotent schema repairs run on install and
	 * post-migration — running them for real catches fatals the container
	 * resolution alone cannot see.
	 *
	 * @dataProvider ensureStepClassesFromInfoXml
	 */
	public function testEnsureStepRunsWithoutFatal(string $class): void
	{
		$step = \OCP\Server::get($class);
		$output = $this->createMock(IOutput::class);
		$output->method('info');
		$step->run($output);
		$this->addToAssertionCount(1);
	}
}
